#!/usr/bin/env node
/* patch-map-pasay.mjs — Angelyn's Cakes: dark map + Pasay address patch
   Usage (from the repo root):
     node patch-map-pasay.mjs --dry-run     show what would happen, write nothing
     node patch-map-pasay.mjs               apply
     node patch-map-pasay.mjs --revert      undo (restores backups, removes added files)
     node patch-map-pasay.mjs --clean-bak   (not used by this patch)
   Safe by design: verifies every source file's SHA-256 first and aborts before writing
   anything on a mismatch; verifies embedded assets; handles CRLF; idempotent. */
import fs from 'node:fs'; import path from 'node:path'; import crypto from 'node:crypto';
const FILES = [{"path":"app/globals.css","origSha":"9cf6f6661f66c6faade3c4422e82fc228954a6cc8c3236ed47e215e4c896d972","newSha":"db59b137a9781f9c78a385831d29bd84cf6691e792c194036298d2806cf4a912","b64":""},{"path":"app/layout.js","origSha":"59be980285cbbe962305e93b2f336b044edfd1ae9b5c8604e324df04f3205a14","newSha":"878352dc492cc977e8790837cbd1ff99c9d748bb1af924659e1c65196812058c","b64":""},{"path":"components/Contact.js","origSha":"c262ac5ea3137f7f5e1ee77a5241f66e1d10f4e79ec262fb4f1ff50c73044eef","newSha":"675de6150dd882f79fbe1bc1280a3a1ffee2459fac7667c2fced146fe6c0de8e","b64":""},{"path":"components/Footer.js","origSha":"18dc7f86b969744b6332da408a1d32b2da70e72dca9062cf9bd82dbaa06aec66","newSha":"f49e621fe02eed25d12d1cc6c706a5bd2aae95e1cda7e27ca185b5f212463fce","b64":""},{"path":"components/LazyMap.js","origSha":"fc40c3bf90bc6f3e4a7bfb3fdb66a005a08d03a75fa59f99216abde97c83f3cd","newSha":"05db83ed30f4d0e477cf7411614c6948916178beace2c978e27c2bfddc038200","b64":""},{"path":"components/Showroom.js","origSha":"012a458347800b94bcf0ba22e995ea153dba7af57b4b3bf8df75c6e3bd7cf31b","newSha":"cb41d22ad34da1ea04a2d56425c6f7cba25e93c270b9a65c4ef2b1db6d36ca41","b64":""},{"path":"lib/data.js","origSha":"3d478de3ec7d4fbdf3ccf6478016a94e17612e0b8cd4ebf4a8d3f1ea70bb8608","newSha":"217aa913cdedf5aefad97a7ec6c50ffdb7910bd893cff9090a25cb80e95ae219","b64":""}];
const ASSETS = [];
const args = new Set(process.argv.slice(2));
const DRY = args.has('--dry-run'), REVERT = args.has('--revert'), CLEAN = false;
const ROOT = process.cwd(), BK = path.join(ROOT, '.patch-backup-map'), MAN = path.join(BK, 'manifest.json');
const sha = b => crypto.createHash('sha256').update(b).digest('hex');
const lf = s => s.replace(/\r\n/g, '\n');
const log = (...a) => console.log(...a);
const die = m => { console.error('\nABORTED, nothing was changed.\n' + m); process.exit(1); };
const abs = p => path.join(ROOT, p);
const ensureDir = p => fs.mkdirSync(path.dirname(p), { recursive: true });

try { const pk = JSON.parse(fs.readFileSync(abs('package.json'), 'utf8')); if (pk.name !== 'angelynscakes') throw 0; }
catch { die('Run this from the repo root (the folder with package.json named "angelynscakes").'); }

if (REVERT) {
  if (!fs.existsSync(MAN)) die('No .patch-backup/manifest.json found, nothing to revert.');
  const m = JSON.parse(fs.readFileSync(MAN, 'utf8'));
  for (const f of m.modified) { log((DRY ? '[dry] ' : '') + 'restore ' + f); if (!DRY) { ensureDir(abs(f)); fs.copyFileSync(path.join(BK, 'files', f), abs(f)); } }
  for (const f of m.added) { log((DRY ? '[dry] ' : '') + 'remove  ' + f); if (!DRY) fs.rmSync(abs(f), { force: true }); }
  for (const f of m.moved || []) { log((DRY ? '[dry] ' : '') + 'move back ' + f); if (!DRY) { ensureDir(abs(f)); fs.renameSync(path.join(BK, 'moved', f), abs(f)); } }
  if (!DRY) { fs.rmSync(BK, { recursive: true, force: true }); log('\nReverted. Backup folder removed.'); }
  process.exit(0);
}

// ---- 1. verify everything BEFORE writing ----
const plan = []; let problems = [];
for (const f of FILES) {
  const p = abs(f.path);
  if (!fs.existsSync(p)) { problems.push('missing file: ' + f.path); continue; }
  const raw = fs.readFileSync(p); const txt = lf(raw.toString('utf8')); const h = sha(Buffer.from(txt, 'utf8'));
  if (h === f.newSha) plan.push({ ...f, action: 'skip' });
  else if (h === f.origSha) plan.push({ ...f, action: 'write', crlf: raw.includes('\r\n') });
  else problems.push(f.path + ' has been edited since this patch was made (hash mismatch)');
}
const newText = f => Buffer.from(f.b64, 'base64').toString('utf8');
for (const f of FILES) if (sha(Buffer.from(newText(f), 'utf8')) !== f.newSha) problems.push('embedded copy of ' + f.path + ' is corrupt');
const aplan = [];
for (const a of ASSETS) {
  const buf = Buffer.from(a.b64, 'base64');
  if (sha(buf) !== a.sha) { problems.push('embedded asset corrupt: ' + a.path + ' (re-download the patch)'); continue; }
  const p = abs(a.path);
  if (fs.existsSync(p) && sha(fs.readFileSync(p)) === a.sha) aplan.push({ ...a, action: 'skip' });
  else aplan.push({ ...a, buf, action: 'write', existed: fs.existsSync(p) });
}
if (problems.length) die(problems.map(x => ' - ' + x).join('\n'));

// ---- 2. apply ----
const prev = fs.existsSync(MAN) ? JSON.parse(fs.readFileSync(MAN, 'utf8')) : { modified: [], added: [], moved: [] };
const man = { modified: [...prev.modified], added: [...prev.added], moved: [...(prev.moved || [])] };
for (const f of plan) {
  if (f.action === 'skip') { log('ok (already patched)  ' + f.path); continue; }
  log((DRY ? '[dry] ' : '') + 'patch ' + f.path);
  if (DRY) continue;
  const bp = path.join(BK, 'files', f.path);
  if (!fs.existsSync(bp)) { ensureDir(bp); fs.copyFileSync(abs(f.path), bp); }
  if (!man.modified.includes(f.path)) man.modified.push(f.path);
  let out = newText(f); if (f.crlf) out = out.replace(/\n/g, '\r\n');
  fs.writeFileSync(abs(f.path), out);
}
for (const a of aplan) {
  if (a.action === 'skip') { log('ok (already present)  ' + a.path); continue; }
  log((DRY ? '[dry] ' : '') + (a.existed ? 'replace ' : 'add     ') + a.path);
  if (DRY) continue;
  if (a.existed) { const bp = path.join(BK, 'files', a.path); if (!fs.existsSync(bp)) { ensureDir(bp); fs.copyFileSync(abs(a.path), bp); } if (!man.modified.includes(a.path)) man.modified.push(a.path); }
  else if (!man.added.includes(a.path)) man.added.push(a.path);
  ensureDir(abs(a.path)); fs.writeFileSync(abs(a.path), a.buf);
}
if (CLEAN) {
  const walk = d => fs.existsSync(d) ? fs.readdirSync(d, { withFileTypes: true }).flatMap(e => e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]) : [];
  for (const full of ['app', 'components', 'public'].flatMap(d => walk(abs(d)))) {
    if (!/\.bak-[^/\\]*$/.test(full)) continue;
    const rel = path.relative(ROOT, full).split(path.sep).join('/');
    log((DRY ? '[dry] ' : '') + 'move out of deploy folder: ' + rel);
    if (DRY) continue;
    const dest = path.join(BK, 'moved', rel); ensureDir(dest); fs.renameSync(full, dest); man.moved.push(rel);
  }
}
if (!DRY) { fs.mkdirSync(BK, { recursive: true }); fs.writeFileSync(path.join(BK, '.gitignore'), '*\n'); fs.writeFileSync(MAN, JSON.stringify(man, null, 2)); }
log(DRY ? '\nDry run complete. Nothing written.' : '\nDone. Run `npm run build` to check, and `node patch-map-pasay.mjs --revert` to undo.');
